"""Run SQL SELECT queries against CSV files. See SPEC.md."""
import csv
import math
import os
import re
from dataclasses import dataclass

from .parser import parse, Expr


class QueryError(Exception):
    """Raised for any problem with a query."""


@dataclass
class Result:
    columns: list
    rows: list


_INT = re.compile(r"-?[0-9]+\Z")
_DEC = re.compile(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)\Z")
_AGGS = {"COUNT", "SUM", "AVG", "MIN", "MAX"}


def _convert(s):
    if s == "": return None
    if _INT.fullmatch(s): return int(s)
    if _DEC.fullmatch(s): return float(s)
    return s


def _truth(x):
    return x is True


def _cmp(a, b):
    if a is None or b is None: return None
    if isinstance(a, bool) or isinstance(b, bool):
        if not isinstance(a, bool) or not isinstance(b, bool): raise QueryError("cannot compare boolean with non-boolean")
    elif isinstance(a, (int, float)) and isinstance(b, (int, float)):
        pass
    elif isinstance(a, str) and isinstance(b, str):
        pass
    else: raise QueryError("incompatible values in comparison")
    return (a > b) - (a < b)


def _has_agg(e):
    return e.kind == "call" and str(e.value).upper() in _AGGS or any(_has_agg(a) for a in e.args)


def _aggregate(e, rows, headers):
    if e.kind == "call" and str(e.value).upper() in _AGGS:
        fn = str(e.value).upper()
        if fn == "COUNT" and e.args and e.args[0].kind == "star": return len(rows)
        vals = [_eval(e.args[0], r, headers) for r in rows] if e.args else []
        vals = [v for v in vals if v is not None]
        if fn == "COUNT": return len(vals)
        if not vals: return None
        if fn == "SUM":
            if any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in vals): raise QueryError("SUM requires numeric values")
            return sum(vals)
        if fn == "AVG":
            if any(isinstance(v, bool) or not isinstance(v, (int, float)) for v in vals): raise QueryError("AVG requires numeric values")
            return float(sum(vals) / len(vals))
        for v in vals[1:]: _cmp(vals[0], v)
        return min(vals) if fn == "MIN" else max(vals)
    if not _has_agg(e): return _eval(e, rows[0] if rows else {}, headers)
    args = tuple(_replace_aggs(a, rows, headers) for a in e.args)
    return _eval(Expr(e.kind, e.value, args, e.text), {}, headers)


def _replace_aggs(e, rows, headers):
    if e.kind == "call" and str(e.value).upper() in _AGGS:
        return Expr("literal", _aggregate(e, rows, headers), (), e.text)
    return Expr(e.kind, e.value, tuple(_replace_aggs(a, rows, headers) for a in e.args), e.text)


def _eval(e, row, headers):
    k, op = e.kind, str(e.value).upper() if e.value is not None else ""
    if k == "literal": return e.value
    if k == "star": return None
    if k == "name":
        idx = next((i for i,h in enumerate(headers) if h.lower() == str(e.value).lower()), None)
        if idx is None: raise QueryError("unknown column: " + str(e.value))
        return row.get(idx)
    if k == "call":
        fn = op
        if fn in _AGGS: raise QueryError("aggregate used outside grouped query")
        vals = [_eval(a,row,headers) for a in e.args]
        arity = {"LOWER":(1,1),"UPPER":(1,1),"LENGTH":(1,1),"ABS":(1,1),"ROUND":(1,2),"COALESCE":(1,None)}
        if fn not in arity: raise QueryError("unknown function: " + fn)
        lo,hi=arity[fn]
        if len(vals)<lo or hi is not None and len(vals)>hi: raise QueryError("wrong number of arguments to " + fn)
        if fn == "COALESCE": return next((v for v in vals if v is not None),None)
        if any(v is None for v in vals): return None
        try:
            if fn in ("LOWER","UPPER","LENGTH"):
                if not isinstance(vals[0],str): raise QueryError(fn+" requires a string")
                return vals[0].lower() if fn=="LOWER" else vals[0].upper() if fn=="UPPER" else len(vals[0])
            if fn=="ABS":
                if isinstance(vals[0],bool) or not isinstance(vals[0],(int,float)): raise QueryError("ABS requires a number")
                return abs(vals[0])
            if any(isinstance(v,bool) or not isinstance(v,(int,float)) for v in vals): raise QueryError("ROUND requires a number")
            if len(vals)==1: return math.floor(vals[0]+0.5) if vals[0]>=0 else math.ceil(vals[0]-0.5)
            n=vals[1]
            if not isinstance(n,int) or isinstance(n,bool): raise QueryError("ROUND precision must be an integer")
            scale=10.0**n
            return float((math.floor(vals[0]*scale+0.5) if vals[0]>=0 else math.ceil(vals[0]*scale-0.5))/scale)
        except OverflowError: raise QueryError("numeric overflow")
    vals=[_eval(a,row,headers) for a in e.args]
    if k == "unary":
        v=vals[0]
        if op=="NOT": return None if v is None else not _truth(v)
        if v is None:return None
        if isinstance(v,bool) or not isinstance(v,(int,float)): raise QueryError("unary minus requires a number")
        return -v
    if k == "binary":
        a,b=vals
        if op=="AND": return False if a is False or b is False else None if a is None or b is None else True
        if op=="OR": return True if a is True or b is True else None if a is None or b is None else False
        if a is None or b is None:return None
        if op=="||": return str(a)+str(b)
        if any(isinstance(x,bool) or not isinstance(x,(int,float)) for x in (a,b)): raise QueryError("arithmetic requires numbers")
        try:
            return a+b if op=="+" else a-b if op=="-" else a*b if op=="*" else None if b==0 else float(a/b)
        except (OverflowError, ValueError): raise QueryError("invalid arithmetic")
    if k == "compare":
        a,b=vals
        c=_cmp(a,b)
        return None if c is None else {"=":c==0,"==":c==0,"!=":c!=0,"<>":c!=0,"<":c<0,"<=":c<=0,">":c>0,">=":c>=0}[op]
    if k == "is_null": return (vals[0] is None) if op=="IS NULL" else (vals[0] is not None)
    if k == "in":
        a, *rest=vals
        if a is not None and any(x is not None and _cmp(a,x)==0 for x in rest): result=True
        elif a is None or any(x is None for x in rest): result=None
        else: result=False
        return (None if result is None else not result) if op=="NOT IN" else result
    if k == "between":
        a,lo,hi=vals
        result=_eval(Expr("binary","AND",(Expr("compare","<=",(Expr("literal",lo),Expr("literal",a))),Expr("compare","<=",(Expr("literal",a),Expr("literal",hi))))),row,headers)
        return None if result is None else (not result if op=="NOT BETWEEN" else result)
    if k == "like":
        a,p=vals
        if a is None or p is None:return None
        if not isinstance(a,str) or not isinstance(p,str): raise QueryError("LIKE requires strings")
        pat="^"+"".join(".*" if c=="%" else "." if c=="_" else re.escape(c) for c in p)+"$"
        v=re.match(pat,a,re.DOTALL) is not None
        return not v if op=="NOT LIKE" else v
    raise QueryError("invalid expression")


def _check_agg(e, where=False, nested=False):
    agg=e.kind=="call" and str(e.value).upper() in _AGGS
    if agg and (where or nested): raise QueryError("invalid aggregate placement")
    for a in e.args: _check_agg(a,where,nested or agg)


def run(sql, directory="."):
    try:
        q=parse(sql)
        path=os.path.join(os.fspath(directory),q.table+".csv")
        with open(path,newline="",encoding="utf-8") as f:
            reader=csv.reader(f)
            try: headers=next(reader)
            except StopIteration: raise QueryError("table has no header")
            rows=[]
            for fields in reader:
                if len(fields)!=len(headers): raise QueryError("row has wrong number of fields")
                rows.append({i:_convert(v) for i,v in enumerate(fields)})
        if len({h.lower() for h in headers}) != len(headers): raise QueryError("duplicate column name")
        if q.where: _check_agg(q.where,True)
        for item in q.columns: _check_agg(item.expr)
        if q.having: _check_agg(q.having)
        for oi in q.order_by: _check_agg(oi.expr)
        if q.where: rows=[r for r in rows if _eval(q.where,r,headers) is True]
        grouped=bool(q.group_by) or any(_has_agg(x.expr) for x in q.columns) or bool(q.having and _has_agg(q.having)) or any(_has_agg(o.expr) for o in q.order_by)
        if grouped:
            if q.group_by:
                bins=[]
                for r in rows:
                    key=tuple(_eval(e,r,headers) for e in q.group_by)
                    bucket=next((b for k,b in bins if _keys_equal(k,key)),None)
                    if bucket is None: bucket=[]; bins.append((key,bucket))
                    bucket.append(r)
                groups=[b for _,b in bins]
            else: groups=[rows]
            rows=groups
        else: rows=[[r] for r in rows]
        # Validate non-aggregate references in grouped queries.
        if grouped:
            gb={e.text for e in q.group_by}
            for item in q.columns:
                _validate_group(item.expr,gb,headers)
        labels=[]; exprs=[]
        for item in q.columns:
            if item.star:
                for i,h in enumerate(headers): labels.append(h); exprs.append(Expr("name",h,(),h))
            else:
                exprs.append(item.expr)
                if item.alias is not None: labels.append(item.alias)
                elif item.expr.kind=="name": labels.append(headers[next(i for i,h in enumerate(headers) if h.lower()==str(item.expr.value).lower())])
                else: labels.append(item.expr.text)
        out=[]
        for group in rows:
            rep=group[0] if group else {}
            if grouped:
                # Group columns outside aggregates evaluate against representative row.
                if q.having and _aggregate(q.having,group,headers) is not True: continue
                vals=tuple(_aggregate(e,group,headers) for e in exprs)
            else: vals=tuple(_eval(e,rep,headers) for e in exprs)
            out.append((vals,group))
        # Stable multi-key sort by applying keys in reverse order.
        for oi in reversed(q.order_by):
            expr=oi.expr
            pos=None
            if expr.kind=="literal" and isinstance(expr.value,int) and not isinstance(expr.value,bool):
                n=expr.value
                if n<1 or n>len(labels): raise QueryError("ORDER BY position out of range")
                pos=n-1
            elif expr.kind=="name":
                matches=[i for i,h in enumerate(labels) if h.lower()==str(expr.value).lower()]
                if matches: pos=matches[0]
            def key(pair):
                v=pair[0][pos] if pos is not None else (_aggregate(expr,pair[1],headers) if grouped else _eval(expr,pair[1][0],headers))
                return (v is not None, v)
            # custom null direction and type-safe comparisons
            out.sort(key=lambda p: _SortKey(key(p)[1],oi.descending), reverse=False)
        if q.distinct:
            seen=set(); unique=[]
            for v,g in out:
                marker=_freeze(v)
                if marker not in seen: seen.add(marker); unique.append((v,g))
            out=unique
        start=q.offset or 0
        if q.limit is not None: out=out[start:start+q.limit]
        elif start: out=out[start:]
        return Result(labels,[v for v,_ in out])
    except QueryError: raise
    except Exception as exc:
        from .parser import ParseError
        if isinstance(exc,(ParseError, OSError, UnicodeError, csv.Error, ValueError, TypeError, KeyError, IndexError)):
            raise QueryError(str(exc)) from exc
        raise QueryError(str(exc)) from exc


def _keys_equal(a,b):
    try:return a==b
    except Exception:return False

def _freeze(v):
    try: hash(v); return v
    except TypeError:return repr(v)

def _validate_group(e,gb,headers,in_agg=False):
    if e.kind=="call" and str(e.value).upper() in _AGGS: return
    if e.kind=="name" and not in_agg and e.text not in gb: raise QueryError("column outside GROUP BY")
    for a in e.args: _validate_group(a,gb,headers,in_agg)


class _SortKey:
    def __init__(self,v,desc): self.v=v; self.desc=desc
    def __lt__(self,other):
        if self.v is None: return self.desc and other.v is not None
        if other.v is None: return not self.desc
        c=_cmp(self.v,other.v)
        return c>0 if self.desc else c<0

