        elif raw[0] == '"':
            out.append(_Tok("QIDENT", raw[1:-1].replace('""', '"'), raw, start, pos))
        elif raw[0].isdigit() or raw[0] == '.':
            out.append(_Tok("NUMBER", float(raw) if '.' in raw else int(raw), raw, start, pos))
        elif raw[0].isalpha() or raw[0] == '_':
            out.append(_Tok("KW" if raw.upper() in _KEYWORDS else "IDENT", raw.upper() if raw.upper() in _KEYWORDS else raw, raw, start, pos))
        else:
            out.append(_Tok(raw, raw, raw, start, pos))
    out.append(_Tok("EOF", None, "", len(sql), len(sql)))
    return out


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.ts = _tokenize(sql)
        self.i = 0

    @property
    def t(self): return self.ts[self.i]

    def take(self):
        t = self.t
        self.i += 1
        return t

    def accept(self, typ):
        if self.t.typ == typ:
            return self.take()
        return None

    def need(self, typ):
        t = self.accept(typ)
        if t is None: raise ParseError("expected %s at position %d" % (typ, self.t.start))
        return t

    def name(self):
        if self.t.typ in ("IDENT", "QIDENT"):
            return self.take().val
        raise ParseError("expected name at position %d" % self.t.start)

    def parse(self):
        self.need("KW") if self.t.typ == "KW" and self.t.val == "SELECT" else self._expected("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))
        cols = []
        if self.accept("*"):
            cols.append(SelectItem(Expr("star", text="*"), star=True))
        else:
            while True:
                e = self.expr()
                alias = None
                if self.accept_kw("AS"):
                    alias = self.name()
                elif self.t.typ in ("IDENT", "QIDENT"):
                    alias = self.name()
                cols.append(SelectItem(e, alias))
                if not self.accept(","): break
        self.need_kw("FROM")
        table = self.name()
        where = None; groups = []; having = None; orders = []; limit = offset = None
        if self.accept_kw("WHERE"): where = self.expr()
        if self.accept_kw("GROUP"):
            self.need_kw("BY"); groups.append(self.expr())
            while self.accept(","): groups.append(self.expr())
        if self.accept_kw("HAVING"): having = self.expr()
        if self.accept_kw("ORDER"):
            self.need_kw("BY")
            while True:
                e = self.expr()
                desc = bool(self.accept_kw("DESC"))
                if not desc: self.accept_kw("ASC")
                orders.append(OrderItem(e, desc))
                if not self.accept(","): break
        if self.accept_kw("LIMIT"):
            limit = self.integer()
            if self.accept_kw("OFFSET"): offset = self.integer()
        if self.accept(";") is None and self.t.typ != "EOF":
            raise ParseError("unexpected token %r at position %d" % (self.t.raw, self.t.start))
        self.need("EOF")
        return Query(distinct, cols, table, where, groups, having, orders, limit, offset)

    def _expected(self, s): raise ParseError("expected %s at position %d" % (s, self.t.start))
    def is_kw(self, s): return self.t.typ == "KW" and self.t.val == s
    def accept_kw(self, s): return self.take() if self.is_kw(s) else None
    def need_kw(self, s):
        if not self.is_kw(s): self._expected(s)
        return self.take()
    def integer(self):
        t = self.need("NUMBER")
        if not isinstance(t.val, int): raise ParseError("expected integer at position %d" % t.start)
        return t.val

    def expr(self): return self.or_expr()
    def or_expr(self):
        x = self.and_expr()
        while self.accept_kw("OR"): x = self.node("binary", "OR", (x, self.and_expr()), x)
        return x
    def and_expr(self):
        x = self.not_expr()
        while self.accept_kw("AND"): x = self.node("binary", "AND", (x, self.not_expr()), x)
        return x
    def not_expr(self):
        if self.accept_kw("NOT"):
            a = self.not_expr(); return self.node("unary", "NOT", (a,), a)
        return self.compare()
    def compare(self):
        x = self.concat()
        op = self.t.typ
        if op in ("=", "!=", "<>", "<", "<=", ">", ">="):
            self.take(); return self.node("compare", op, (x, self.concat()), x)
        neg = False
        if self.is_kw("NOT") and self.ts[self.i+1].typ == "KW" and self.ts[self.i+1].val in ("IN", "BETWEEN", "LIKE"):
            self.take(); neg = True
        if self.accept_kw("IS"):
            n = bool(self.accept_kw("NOT")); self.need_kw("NULL")
            return self.node("is_null", "IS NOT NULL" if n else "IS NULL", (x,), x)
        if self.accept_kw("IN"):
            self.need("("); args = [x]
            if self.t.typ != ")":
                args.append(self.expr())
                while self.accept(","): args.append(self.expr())
            self.need(")")
            return self.node("in", "NOT IN" if neg else "IN", tuple(args), x)
        if self.accept_kw("BETWEEN"):
            lo = self.concat(); self.need_kw("AND"); hi = self.concat()
            return self.node("between", "NOT BETWEEN" if neg else "BETWEEN", (x,lo,hi), x)
        if self.accept_kw("LIKE"):
            return self.node("like", "NOT LIKE" if neg else "LIKE", (x,self.concat()), x)
        if neg: raise ParseError("expected IN, BETWEEN, or LIKE")
        return x
    def concat(self): return self.left_assoc(self.add, ("||",))
    def add(self): return self.left_assoc(self.mul, ("+", "-"))
    def mul(self): return self.left_assoc(self.unary, ("*", "/"))
    def left_assoc(self, sub, ops):
        x = sub()
        while self.t.typ in ops:
            op = self.take().typ; x = self.node("binary", op, (x, sub()), x)
        return x
    def unary(self):
        if self.accept("-"):
            a = self.unary(); return self.node("unary", "-", (a,), a)
        return self.primary()
    def primary(self):
        t = self.t
        if t.typ == "NUMBER":
            self.take(); return Expr("literal", t.val, (), t.raw, t.start)
        if t.typ == "STRING":
            self.take(); return Expr("literal", t.val, (), t.raw, t.start)
        if self.accept_kw("NULL"): return Expr("literal", None, (), "NULL", t.start)
        if self.accept_kw("TRUE"): return Expr("literal", True, (), "TRUE", t.start)
        if self.accept_kw("FALSE"): return Expr("literal", False, (), "FALSE", t.start)
        if self.accept("("):
            start = t.start; x = self.expr(); end = self.need(")").end
            return Expr(x.kind, x.value, x.args, self.sql[start:end], start)
        if t.typ in ("IDENT", "QIDENT"):
            self.take()
            if self.accept("("):
                args = []
                if not self.accept(")"):
                    if self.accept("*"): args.append(Expr("star", text="*"))
                    else: args.append(self.expr())
                    while self.accept(","): args.append(self.expr())
                    self.need(")")
                return Expr("call", t.val.upper(), tuple(args), self.sql[t.start:self.ts[self.i-1].end], t.start)
            return Expr("name", t.val, (), t.raw, t.start)
        raise ParseError("expected expression at position %d" % t.start)

    def node(self, kind, value, args, left):
        end = self.ts[self.i-1].end
        return Expr(kind, value, tuple(args), self.sql[left.start:end], left.start)


def parse(sql):
    """Parse one SELECT statement and return a Query AST."""
    if not isinstance(sql, str): raise ParseError("query must be a string")
    return _Parser(sql).parse()
